for cat_key, prompts in categories.items():
    cat = PROMPTS / cat_key
    for filename, title, tags, difficulty, prompt_text in prompts:
        write(cat / filename, make_prompt(cat_key.split("-", 1)[1], title, tags, difficulty, prompt_text))
    print(f"  ✅ {cat_key}: {len(prompts)} prompts written")

print(f"\n🎉 All categories 15-20 complete!")
